'use strict';
// Purpose-built WeChat IDE automation against the isolated mock project only.
const fs=require('node:fs'),path=require('node:path'),{spawn}=require('node:child_process');
const root=path.resolve(__dirname,'..'),fixture=path.resolve(root,'../.rural-quiz-runtime/native-visual-review'),qa=path.join(root,'qa/inner-polish-20261020');
const group=process.argv[2]||'quiz',themes=process.argv[3]?process.argv[3].split(','):['ecology','culture','red','industry'];const events=[];
async function call(tool,args){return new Promise((resolve,reject)=>{const child=spawn('/usr/local/bin/wechatide',['-c','Codex',tool,'--project',fixture,...args]);let out='',err='';const timer=setTimeout(()=>{child.kill('SIGTERM');reject(Error(tool+' timeout'));},45000);child.stdout.on('data',b=>out+=b);child.stderr.on('data',b=>err+=b);child.on('error',reject);child.on('close',code=>{clearTimeout(timer);let r;try{r=JSON.parse(out.slice(out.indexOf('{')));}catch{return reject(Error(err||out));}events.push({tool,args,ok:r.ok,result:r.result||r.message});fs.writeFileSync(path.join(qa,group+'-native-events.json'),JSON.stringify(events,null,2)+'\n');if(code||!r.ok||r.result?.success===false)reject(Error(tool+': '+(r.message||r.result?.error)));else resolve(r.result);});});}
(async()=>{for(const theme of themes){await call('simulator_open_page',['--page','pages/game/index','--query','theme='+theme+'&review=1&controls=0&scenario='+group]);await call('simulator_screenshot',['--path',path.join(qa,theme+'-'+group+'.png'),'--optimize','false','--wait-for-selector',group==='quiz'||group==='long'?'.question-title':group==='home'?'.route-canvas':'.theme-modal']);console.log('Captured '+theme+' '+group);}})().catch(e=>{console.error(e);process.exit(1);});
